window.ROLES={"retail":{"label":"Bán hàng tại cửa hàng","emoji":"🛍️","scenarios":[{"k":"r_rt_browse","l":"Khách vào xem hàng","s":"You are a foreign customer walking into a home appliance store. At first say you are just looking, then ask about an air purifier for a small bedroom."},{"k":"r_rt_size","l":"Hỏi size & màu","s":"You are a customer in a clothing shop. Ask if a jacket comes in another colour and a bigger size, then ask to try it on."},{"k":"r_rt_pay","l":"Thanh toán tại quầy","s":"You are a customer at the checkout. Ask if you can pay by foreign card, ask about a membership discount and ask for a VAT invoice."},{"k":"r_rt_return","l":"Đổi hàng tại cửa hàng","s":"You are a customer who wants to exchange shoes you bought three days ago because they are too small. You have the receipt."}],"dialogues":[{"them":"Excuse me, do you have these shoes in size 42?","opts":[{"t":"Let me check for you. Please have a seat, I'll be right back.","good":true,"fb":"Nhận kiểm tra + mời khách ngồi chờ — lịch sự."},{"t":"Size 42 no have.","good":false,"fb":"Dịch từng chữ 'không có': 'Sorry, we don't have size 42.' — lại chưa kiểm tra kho."},{"t":"Your foot too big.","good":false,"fb":"Thiếu động từ và bình luận cơ thể khách — rất bất lịch sự."}]},{"them":"Can I try this on?","opts":[{"t":"Yes, you can try on there.","good":false,"fb":"Thiếu tân ngữ: 'try it on'."},{"t":"Of course. The fitting room is just over there, on the left.","good":true,"fb":"Đồng ý + chỉ đường rõ ràng."},{"t":"Try is free.","good":false,"fb":"Dịch từng chữ, nghe kỳ và không chỉ phòng thử."}]},{"them":"Is this on sale?","opts":[{"t":"Yes, sale 30.","good":false,"fb":"Thiếu động từ và đơn vị: 'Yes, it's 30% off.'"},{"t":"No sale, but it's good.","good":false,"fb":"Trả lời cụt, không đưa thông tin giá hay lợi ích."},{"t":"Yes, it's 30% off this week, so it's 700,000 dong now.","good":true,"fb":"Xác nhận + mức giảm + giá sau giảm."}]},{"them":"Can I get a discount with my membership card?","opts":[{"t":"Yes, members get 5% off. Could I scan your card, please?","good":true,"fb":"Xác nhận quyền lợi + xin thẻ lịch sự."},{"t":"Yes, give me card.","good":false,"fb":"Mệnh lệnh cộc, thiếu 'your' và 'please'."},{"t":"Membership only for VIP.","good":false,"fb":"Thiếu động từ, thông tin mơ hồ, dễ làm khách phật ý."}]},{"them":"It's a bit too expensive for me.","opts":[{"t":"Cheap one is not good quality.","good":false,"fb":"Thiếu mạo từ và ép khách mua đồ đắt."},{"t":"I understand. This one is similar but 20% cheaper. Would you like to see it?","good":true,"fb":"Đồng cảm + gợi ý lựa chọn vừa túi tiền."},{"t":"So you don't buy?","good":false,"fb":"Dùng câu khẳng định làm câu hỏi, nghe như trách khách."}]},{"them":"Can I pay with a foreign credit card?","opts":[{"t":"Yes, can pay.","good":false,"fb":"Thiếu chủ ngữ: 'Yes, you can.'"},{"t":"Foreign card is problem, pay cash better.","good":false,"fb":"Thiếu mạo từ/động từ và gây bất tiện cho khách không cần thiết."},{"t":"Yes, we accept all major international cards. Please tap it here.","good":true,"fb":"Trả lời rõ + hướng dẫn thao tác."}]}]},"cs":{"label":"CSKH · Call center","emoji":"🎧","scenarios":[{"k":"r_cs_bill","l":"Thắc mắc hóa đơn","s":"You are a customer calling because this month's phone bill is 200,000 dong higher than usual. I am the call center agent. Answer my identity questions, then explain the problem."},{"k":"r_cs_angry","l":"Khách giận dữ","s":"You are an angry customer. Your internet has been down for two days and you have called twice before. Calm down only if I apologise and give a clear plan."},{"k":"r_cs_transfer","l":"Chuyển máy & giữ máy","s":"You are a customer with a technical problem the agent cannot fix. Accept being put on hold, then ask who you will be transferred to and how long it will take."},{"k":"r_cs_followup","l":"Gọi lại chăm sóc","s":"You are a customer who had a washing machine repaired last week. I am calling to follow up. Say it works, but mention a small noise and ask what to do."}],"dialogues":[{"them":"Hello? I'm calling about my account.","opts":[{"t":"OK, what is your account?","good":false,"fb":"Chưa chào, chưa xác minh, hỏi mơ hồ."},{"t":"Thank you for calling. My name is Linh. For security, could I have your full name and date of birth, please?","good":true,"fb":"Chào + giới thiệu + xác minh danh tính lịch sự."},{"t":"Give me your ID number.","good":false,"fb":"Mệnh lệnh cộc lốc, thiếu 'please'."}]},{"them":"Why is my bill so high this month?","opts":[{"t":"Because you use too much.","good":false,"fb":"Kết luận khi chưa kiểm tra, nghe như trách khách."},{"t":"I don't know why high.","good":false,"fb":"Sai cấu trúc ('why it's so high') và không có hướng xử lý."},{"t":"Let me check that for you. May I put you on hold for about one minute?","good":true,"fb":"Nhận kiểm tra + xin phép giữ máy + thời gian."}]},{"them":"I've called three times and nobody fixed it!","opts":[{"t":"I'm very sorry. I'll take care of this personally and call you back by 3 p.m. today.","good":true,"fb":"Xin lỗi + nhận trách nhiệm + hẹn giờ cụ thể."},{"t":"Calm down, please.","good":false,"fb":"Bảo khách bình tĩnh khiến họ bực hơn."},{"t":"Before is other agent, not me.","good":false,"fb":"Thiếu động từ, đổ lỗi cho đồng nghiệp."}]},{"them":"Can I speak to your supervisor?","opts":[{"t":"Supervisor no time.","good":false,"fb":"Thiếu động từ và từ chối cộc."},{"t":"Of course. I'll transfer you now. It may take about two minutes, so please stay on the line.","good":true,"fb":"Đồng ý + báo thời gian + dặn giữ máy."},{"t":"Why? I am not good?","good":false,"fb":"Sai cấu trúc câu hỏi ('Am I not…?') và nghe tự ái."}]},{"them":"Sorry, can you speak more slowly?","opts":[{"t":"I speak slowly already.","good":false,"fb":"Cãi khách; đúng ra phải nói chậm lại."},{"t":"You don't understand English?","good":false,"fb":"Nghe xúc phạm khách — hãy nói chậm và nhắc lại."},{"t":"Of course. I said your new plan starts on the first of next month.","good":true,"fb":"Nói chậm lại + nhắc lại ý chính."}]},{"them":"No, that's all. Thank you.","opts":[{"t":"You're welcome. Thank you for calling, and have a nice day!","good":true,"fb":"Kết thúc cuộc gọi chuẩn, thân thiện."},{"t":"OK bye.","good":false,"fb":"Quá cộc cho lời kết cuộc gọi CSKH."},{"t":"Please give me five stars.","good":false,"fb":"Xin đánh giá thẳng thừng, thiếu chuyên nghiệp."}]}]},"telesales":{"label":"Telesales","emoji":"📞","scenarios":[{"k":"r_ts_cold","l":"Gọi khách lần đầu","s":"You are a busy person receiving my first call about a home internet plan. Ask who I am and how I got your number. Give me thirty seconds to explain."},{"k":"r_ts_busy","l":"Khách bận, hẹn gọi lại","s":"You are a customer who is driving when I call. Ask me to call back later and agree on a time."},{"k":"r_ts_objection","l":"Khách từ chối","s":"You are a customer I am calling about a health insurance plan. Say it's too expensive and you already have one. Stay polite but hard to convince."},{"k":"r_ts_close","l":"Chốt đơn qua điện thoại","s":"You are interested in the product I'm selling by phone. Ask about the price, delivery and how to pay, then agree to order if my answers are clear."}],"dialogues":[{"them":"Who is this?","opts":[{"t":"I am Nam. I sell air purifier.","good":false,"fb":"Thiếu 's' và vào thẳng bán hàng, không hỏi khách có rảnh không."},{"t":"You don't know me, but listen.","good":false,"fb":"Nghe áp đặt — khách sẽ cúp máy."},{"t":"Hi, this is Nam from Zenta Home. I'm calling about our new air purifier offer. Do you have two minutes?","good":true,"fb":"Giới thiệu tên + công ty + lý do + xin phép thời gian."}]},{"them":"I'm not interested.","opts":[{"t":"I understand. Can I just ask: do you already use an air purifier at home?","good":true,"fb":"Tôn trọng + một câu hỏi ngắn để giữ cuộc trò chuyện."},{"t":"Why you not interested?","good":false,"fb":"Thiếu trợ động từ ('Why aren't you…') và nghe như tra hỏi."},{"t":"But it is very cheap, you must buy!","good":false,"fb":"Ép buộc — khách càng từ chối."}]},{"them":"I'm driving right now.","opts":[{"t":"It's OK, only one minute.","good":false,"fb":"Không tôn trọng việc khách đang lái xe."},{"t":"Sorry to bother you. When would be a good time to call you back?","good":true,"fb":"Xin lỗi + hỏi giờ gọi lại — tôn trọng an toàn của khách."},{"t":"I call again later.","good":false,"fb":"Thiếu 'will' và không hẹn giờ cụ thể: 'I'll call you back at 5.'"}]},{"them":"How did you get my number?","opts":[{"t":"I have many numbers.","good":false,"fb":"Né câu hỏi, làm khách nghi ngờ."},{"t":"Secret.","good":false,"fb":"Cộc và thiếu minh bạch."},{"t":"You signed up on our website last month. If you prefer, I can remove your number from our list.","good":true,"fb":"Giải thích nguồn số + tôn trọng quyền từ chối của khách."}]},{"them":"How much is it?","opts":[{"t":"It's 2.9 million dong, and this month you also get free delivery and installation.","good":true,"fb":"Báo giá + ưu đãi kèm theo."},{"t":"It 2.9 million.","good":false,"fb":"Thiếu động từ 'is'."},{"t":"Very cheap, you will love it.","good":false,"fb":"Né giá cụ thể — khách sẽ mất tin tưởng."}]},{"them":"OK, I'll order one.","opts":[{"t":"OK. You give address.","good":false,"fb":"Mệnh lệnh cộc; nên nói 'Could I have your address, please?'"},{"t":"Great! Let me confirm your name and delivery address, and I'll text you an order confirmation.","good":true,"fb":"Vui mừng + xác nhận thông tin + bước tiếp theo."},{"t":"Why only one? Buy two is cheaper.","good":false,"fb":"Khách vừa đồng ý đã ép thêm — dễ đổi ý; sai ngữ pháp ('Buying two is cheaper')."}]}]},"b2b":{"label":"Sale B2B · Account","emoji":"🤝","scenarios":[{"k":"r_bb_meet","l":"Gặp khách doanh nghiệp","s":"You are the purchasing manager of a foreign-owned factory. I am an account manager visiting you. Ask about our products, minimum order and delivery times."},{"k":"r_bb_quote","l":"Thương lượng báo giá","s":"You received my quotation for 500 office chairs. Say the price is 10% higher than another supplier and ask for better payment terms."},{"k":"r_bb_issue","l":"Xử lý sự cố với khách lớn","s":"You are a key customer. Our last delivery was one week late and your work was delayed. Ask what happened and what we will do to prevent it."},{"k":"r_bb_renew","l":"Gia hạn hợp đồng năm","s":"You are a long-term customer. Your yearly contract ends next month. Ask about new prices and what extra service we can offer."}],"dialogues":[{"them":"What's your minimum order?","opts":[{"t":"Our minimum order is 100 units, but for a first trial order we can accept 50.","good":true,"fb":"Thông tin rõ + linh hoạt để mở cơ hội hợp tác."},{"t":"Minimum is many.","good":false,"fb":"Mơ hồ, không có con số."},{"t":"You must order 100, no less.","good":false,"fb":"Cứng nhắc, dễ mất khách mới."}]},{"them":"Your price is higher than your competitor's.","opts":[{"t":"Their quality is bad.","good":false,"fb":"Chê đối thủ thiếu căn cứ — không chuyên nghiệp."},{"t":"I understand. Our price includes a two-year warranty and on-site support, which saves you money in the long run.","good":true,"fb":"Công nhận + chứng minh giá trị tổng thể."},{"t":"OK, I reduce 20%.","good":false,"fb":"Thiếu 'will' và giảm giá ngay, quá nhiều, không thương lượng."}]},{"them":"Can we pay 60 days after delivery?","opts":[{"t":"Yes, no problem, 90 days also OK.","good":false,"fb":"Hứa vượt quyền hạn khi chưa hỏi cấp trên."},{"t":"60 days is too long, cannot.","good":false,"fb":"Thiếu chủ ngữ và từ chối cứng nhắc."},{"t":"Our standard terms are 30 days, but let me check with my manager and get back to you tomorrow.","good":true,"fb":"Nêu điều khoản chuẩn + không hứa bừa + hẹn thời gian."}]},{"them":"The last delivery was a week late.","opts":[{"t":"I'm very sorry. There was a problem with our supplier. We've changed our process, and I'll update you on every order from now on.","good":true,"fb":"Xin lỗi + nguyên nhân + biện pháp phòng ngừa."},{"t":"Delivery late is normal in rainy season.","good":false,"fb":"Coi chậm trễ là bình thường — khách lớn sẽ không chấp nhận."},{"t":"Sorry, is not my department.","good":false,"fb":"Thiếu chủ ngữ 'it' và né trách nhiệm của người quản lý khách hàng."}]},{"them":"Could you send me a formal quotation?","opts":[{"t":"OK, I send later.","good":false,"fb":"Thiếu 'will', thiếu tân ngữ và không có thời hạn."},{"t":"Certainly. I'll email it to you by Wednesday, with prices, delivery times and payment terms.","good":true,"fb":"Đồng ý + thời hạn + nội dung báo giá rõ ràng."},{"t":"Price same as I said, no need.","good":false,"fb":"Bỏ qua yêu cầu chính thức của khách doanh nghiệp."}]},{"them":"We're happy to sign the contract.","opts":[{"t":"Finally! Sign quickly please.","good":false,"fb":"Nghe sốt ruột, thiếu chuyên nghiệp."},{"t":"OK thank.","good":false,"fb":"Cộc, thiếu 's', không nói bước tiếp theo."},{"t":"That's great news! I'll send the contract today, and I'll be your main contact for every order.","good":true,"fb":"Vui mừng + bước tiếp theo + cam kết chăm sóc lâu dài."}]}]}};
